// One item per workflow, each already shaped as the GitHub contents API wants.
const payload = $input.first().json;
const workflows = Array.isArray(payload?.data) ? payload.data : (Array.isArray(payload) ? payload : []);

if (!workflows.length) {
  throw new Error('No workflows came back — check N8N_URL and N8N_API_KEY before assuming the instance is empty.');
}

return workflows.map((wf) => {
  // Strip the fields that move on their own. Without this every run is a commit.
  const { active, versionId, updatedAt, createdAt, ...stable } = wf;

  const body = JSON.stringify(stable, null, 2);

  return {
    json: {
      id: wf.id,
      name: wf.name,
      path: `workflows/${wf.id}.json`,
      // GitHub takes file content base64-encoded.
      contentBase64: Buffer.from(body, 'utf8').toString('base64'),
    },
  };
});

// A backup job that fails quietly is worse than no backup job.
const results = $input.all().map(i => Number(i.json?.statusCode ?? 0));
const written = results.filter(s => s === 200 || s === 201).length;
const failed = results.length - written;

if (failed > 0) {
  throw new Error(`${failed} of ${results.length} workflows failed to back up.`);
}

return [{ json: { backedUp: written, at: new Date().toISOString() } }];
